### AuthManager.cs
`using System.Collections;
using UnityEngine;
using Firebase;
using Firebase.Auth;
using TMPro;
using Facebook.Unity;
public class AuthManager : MonoBehaviour{
//Firebase variables
[Header("Firebase")]
public DependencyStatus dependencyStatus;
public FirebaseAuth auth;
public FirebaseUser User;
//Login variables
[Header("Login")]
public TMP_InputField emailLoginField;
public TMP_InputField passwordLoginField;
public TMP_Text warningLoginText;
public TMP_Text confirmLoginText;
//Register variables
[Header("Register")]
public TMP_InputField usernameRegisterField;
public TMP_InputField emailRegisterField;
public TMP_InputField passwordRegisterField;
public TMP_InputField passwordRegisterVerifyField;
public TMP_Text warningRegisterText;
void Awake() {
//Check that all of the necessary dependencies for Firebase are present on the system
FirebaseApp.CheckAndFixDependenciesAsync().ContinueWith(task =>{
dependencyStatus = task.Result;
if (dependencyStatus == DependencyStatus.Available){
//If they are avalible Initialize Firebase
InitializeFirebase();
}
else {
Debug.LogError("Could not resolve all Firebase dependencies: " + dependencyStatus);
}
});
}
private void InitializeFirebase() {
Debug.Log("Setting up Firebase Auth");
//Set the authentication instance object
auth = FirebaseAuth.DefaultInstance;
auth.StateChanged += AuthStateChanged;
AuthStateChanged(this, null);
}
private void OnDestroy(){
auth.StateChanged -= AuthStateChanged;
auth = null;
}
public void LoginButton() {
Login(emailLoginField.text, passwordLoginField.text);
}
public void RegisterButton(){
StartCoroutine(Register(emailRegisterField.text, passwordRegisterField.text, usernameRegisterField.text));
}
public void Login(string _email, string _password){
var LoginTask = auth.SignInWithEmailAndPasswordAsync(_email, _password);
LoginTask.ContinueWith(task => {
if (task.IsCanceled || task.IsFaulted) {
Firebase.FirebaseException e =
task.Exception.Flatten().InnerExceptions[0] as Firebase.FirebaseException;
GetErrorMessage((AuthError)e.ErrorCode, warningLoginText);
return;
}
if (task.IsCompleted) {
User = LoginTask.Result;
Debug.LogFormat("User signed in successfully: {0} ({1})", User.DisplayName, User.Email);
warningLoginText.text = "";
confirmLoginText.text = "Logged In";
UIControllerLogin.instance.MainScreenScene();
}
});
}
public IEnumerator Register(string _email, string _password, string _username) {
if (_username == "") {
//If the username field is blank show a warning
warningRegisterText.text = "Missing Username";
}
else if (passwordRegisterField.text != passwordRegisterVerifyField.text) {
//If the password does not match show a warning
warningRegisterText.text = "Password Does Not Match!";
}
else {
//Call the Firebase auth signin function passing the email and password
var RegisterTask = auth.CreateUserWithEmailAndPasswordAsync(_email, _password);
//Wait until the task completes
yield return new WaitUntil(predicate: () => RegisterTask.IsCompleted);
if (RegisterTask.Exception != null) {
//If there are errors handle them
FirebaseException e =
RegisterTask.Exception.Flatten().InnerExceptions[0] as FirebaseException;
GetErrorMessage((AuthError)e.ErrorCode, warningRegisterText);
}
else {
//User has now been created
//Now get the result
